{"rob": "robolang 1.3;

task put_box(robot r, object box, location shelf, location table, location dock) {
    goal { object_at box table; robot_at r dock; }
    plan {
        move r to shelf;
        grasp r box;
        move r to table;
        place r box at table;
        move r to dock;
    }
}
", "task": "put_box", "bindings": [{"param": "r", "id": "arm1"}, {"param": "box", "id": "box1"}, {"param": "shelf", "id": "shelf"}, {"param": "table", "id": "table"}, {"param": "dock", "id": "dock"}]}
